css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: var(--loader-size); position: relative; }
.loader span { position: absolute; top: 0; left: 0; width: calc(var(--loader-size) * .18); height: calc(var(--loader-size) * .18); border-radius: 28%; background: var(--accent); animation: lap calc(var(--loader-speed) * 2.4) linear infinite; }
.loader span:nth-child(1) { background: var(--accent-2); animation-delay: 0s; }
.loader span:nth-child(2) { animation-delay: calc(var(--loader-speed) * -.18); }
.loader span:nth-child(3) { animation-delay: calc(var(--loader-speed) * -.36); }
.loader span:nth-child(4) { animation-delay: calc(var(--loader-speed) * -.54); }
@keyframes lap { 0% { transform: translate(0, 0); } 25% { transform: translate(calc(var(--loader-size) * .82), 0); } 50% { transform: translate(calc(var(--loader-size) * .82), calc(var(--loader-size) * .82)); } 75% { transform: translate(0, calc(var(--loader-size) * .82)); } 100% { transform: translate(0, 0); } }
